// Prepare a small, random policy-like blob in a temporary file to satisfy FILE* readability
// and keep runtime fast (<2048 bytes). The actual contents may or may not be a valid SELinux policy.
std::string blob = FUZZ_PARAM_STR();
size_t write_len = blob.size();
if (write_len > 2048) { write_len = 2048; }

// Use a fuzz-provided filename; open with read/write to control size and ensure readability.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(path, "wb+");
if (!fp) { FUZZ_BAIL(); }

// Write the constrained blob and rewind so the target function reads from the beginning.
size_t nw = fwrite(blob.data(), 1, write_len, fp);
if (nw != write_len) {
    fclose(fp);
    FUZZ_BAIL();
}
if (fflush(fp) != 0) {
    fclose(fp);
    FUZZ_BAIL();
}
if (fseek(fp, 0, SEEK_SET) != 0) {
    fclose(fp);
    FUZZ_BAIL();
}

// Invoke the target function with a valid, readable FILE*.
int ret = sepol_set_policydb_from_file(fp);

// Close the file to avoid descriptor leakage irrespective of success/failure.
fclose(fp);

// No strong success invariant is asserted here because the input may be invalid policy data.
// Track return value in global attrs for potential downstream consumers.
FUZZ_SET_ATTR_INT_GLOBAL("sepol_set_policydb_from_file_ret", ret);

// Validation: The stub guarantees a non-null readable FILE* and bounds the input size; errors from the API are allowed and recorded.

// Create a new sepol_policy_file_t and return it as output
sepol_policy_file_t *pf = nullptr;
int rc = sepol_policy_file_create(&pf);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_ASSERT(pf != nullptr, "sepol_policy_file_create returned success but pf is null");
// Track initial mode as unknown; future stubs may configure mem/fp
FUZZ_SET_ATTR_STR(pf, "mode", "unset");
// pf persists; return as output

// Free a sepol_policy_file_t previously created. We do not attempt to close FILE* or free user buffers
// because ownership is unspecified; we avoid double-close/double-free risks here.
sepol_policy_file_free(pf);
// No outputs; pf is consumed

// Configure policy file for memory-backed operations. To avoid dangling pointers after this stub returns,
// use the len==0 mode which only enables size computation on later writes and does not dereference data.
// This satisfies the API without requiring the buffer to persist.
std::string tmp = FUZZ_PARAM_STR();
size_t len = 0; // per API: len==0 => only compute required length on later write
char *data = nullptr; // ignored when len==0
sepol_policy_file_set_mem(pf, data, len);
FUZZ_SET_ATTR_STR(pf, "mode", "mem");
FUZZ_SET_ATTR_INT(pf, "mem_len_known", 0);
// pf persists as output

// Retrieve computed length from a previous write into this policy file
size_t out_len = 0;
int rc = sepol_policy_file_get_len(pf, &out_len);
if (rc != 0) { FUZZ_BAIL(); }
// Record for later use
FUZZ_SET_ATTR_INT(pf, "last_len", (int)(out_len & 0x7fffffff));
// pf persists

// Configure the policy file to use a FILE*. Use a temporary fuzz file path and open it now.
const char *path = FUZZ_PARAM_FILENAME();
