import random
import string
from typing import List, Tuple

# Target data type: SELinux context string
# Form: user:role:type[:mls]
# - user, role, type: identifiers (alnum, underscore, dash, dot) without ':'
# - mls (optional): common forms include:
#   * sX
#   * sX:cA
#   * sX:cA.cB
#   * sX-sY
#   * sX:cA.cB-sY:cC.cD
# This generator focuses on producing syntactically valid and diverse contexts.
# It also sometimes emits only the context (for FUZZ_PARAM_STR), and sometimes
# wraps multiple contexts separated by newlines to seed corpus for filename-based
# fuzzers (still valid buffers but consumers will usually take the first line).

SAFE_CHARS = string.ascii_lowercase + string.digits + "_-."

def _rand_ident(rng: random.Random, min_len: int = 1, max_len: int = 16) -> str:
    n = rng.randint(min_len, max_len)
    # ensure starts with alpha to be more typical, but allow digits occasionally
    if n == 0:
        n = 1
    first_pool = string.ascii_lowercase + (string.digits if rng.random() < 0.2 else "")
    s = [rng.choice(first_pool)]
    for _ in range(n - 1):
        s.append(rng.choice(SAFE_CHARS))
    return "".join(s)

def _user(rng: random.Random) -> str:
    # Common SELinux users
    common = [
        "system_u", "user_u", "staff_u", "sysadm_u", "unconfined_u",
        "guest_u", "xguest_u"
    ]
    if rng.random() < 0.6:
        return rng.choice(common)
    return _rand_ident(rng, 1, 12) + "_u"

def _role(rng: random.Random) -> str:
    common = [
        "object_r", "system_r", "sysadm_r", "unconfined_r", "staff_r"
    ]
    if rng.random() < 0.6:
        return rng.choice(common)
    return _rand_ident(rng, 1, 12) + "_r"

def _type(rng: random.Random) -> str:
    common = [
        "object_t", "init_t", "unconfined_t", "kernel_t", "device_t",
        "user_home_t", "var_t", "tmp_t", "httpd_t", "sshd_t"
    ]
    if rng.random() < 0.6:
        return rng.choice(common)
    return _rand_ident(rng, 1, 20) + "_t"

def _mls_level(rng: random.Random) -> str:
    # s0..s15 typical
    s = f"s{rng.randint(0, 15)}"
    # optionally add categories
    if rng.random() < 0.7:
        # pick form: cX or cX.cY or cX,cY,cZ
        form = rng.random()
        if form < 0.5:
            s += f":c{rng.randint(0, 1023)}"
        elif form < 0.85:
            a = rng.randint(0, 1023)
            b = rng.randint(0, 1023)
            lo, hi = (a, b) if a <= b else (b, a)
            s += f":c{lo}.c{hi}"
        else:
            # a small comma list of categories and/or ranges
            parts: List[str] = []
            count = rng.randint(1, 4)
            for _ in range(count):
                if rng.random() < 0.6:
                    parts.append(f"c{rng.randint(0, 63)}")
                else:
                    a = rng.randint(0, 63)
                    b = rng.randint(0, 63)
                    lo, hi = (a, b) if a <= b else (b, a)
                    parts.append(f"c{lo}.c{hi}")
            s += ":" + ",".join(parts)
    return s

def _mls_range(rng: random.Random) -> str:
    # choose between single level or range
    if rng.random() < 0.6:
        return _mls_level(rng)
    lo = _mls_level(rng)
    hi = _mls_level(rng)
    return f"{lo}-{hi}"

def _make_context(rng: random.Random, with_mls_prob: float = 0.7) -> str:
    u = _user(rng)
    r = _role(rng)
    t = _type(rng)
    ctx = f"{u}:{r}:{t}"
    if rng.random() < with_mls_prob:
        ctx += ":" + _mls_range(rng)
    return ctx

def _maybe_pack_multiple(rng: random.Random, primary: str) -> bytes:
    # Sometimes return multiple newline-separated contexts to seed corpora.
    if rng.random() < 0.15:
        n_extra = rng.randint(1, 3)
        lines = [primary]
        for _ in range(n_extra):
            lines.append(_make_context(rng))
        buf = "\n".join(lines)
        return buf.encode("utf-8")[:4096]
    return primary.encode("utf-8")

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a generation strategy suitable for the listed fuzzers
    #  - sepol_check_context: any syntactically plausible string
    #  - sepol_context_from_string: prefers user:role:type[:mls]
    #  - sepol_context_to_sid: expects valid context; we provide proper contexts

    # Occasionally generate minimal context without MLS to diversify
    if rng.random() < 0.25:
        u = _rand_ident(rng, 1, 8)
        r = _rand_ident(rng, 1, 8)
        t = _rand_ident(rng, 1, 12) + "_t"
        ctx = f"{u}:{r}:{t}"
        return _maybe_pack_multiple(rng, ctx)

    # Common valid contexts with MLS
    ctx = _make_context(rng, with_mls_prob=0.9)
    data = _maybe_pack_multiple(rng, ctx)

    # Ensure buffer length bounds
    if len(data) > 4096:
        data = data[:4096]
    if len(data) == 0:
        data = b"x:x:x"
    return data
